IV='https://healthservice.hse.ie/documents/6567/232_v5_Vinorelbine_IV.pdf'; ORAL='https://healthservice.hse.ie/documents/6363/259_Vinorelbine_Oral.pdf'; IVSPC='https://assets.hpra.ie/products/Human/26035/Licence_PA0329-011-003_08012024110935.pdf'; ORALSPC='https://assets.hpra.ie/products/Human/38141/Licence_PA2315-253-001_09042025122220.pdf'; ANTI='https://healthservice.hse.ie/documents/7152/Classification_Document_for_Systemic_Anti-_Cancer_Therapy_SACT_Induced_Nausea__pWgDCrm.pdf'
def save(name,v):
 def clean(x,key=''):
  if isinstance(x,dict):return {k:clean(v,k) for k,v in x.items()}
  if isinstance(x,list):return [clean(v,key) for v in x]
  if isinstance(x,str) and not any(t in key.lower() for t in ['url','sha256','version','checked','code','release','evidence_key','citation']) and not x.startswith('https://'):
   x=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',x);x=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',x)
   return x.replace('CYP 3 A 4','CYP3A4').replace('5 HT 3','5-HT3').replace('5-HT 3','5-HT3').replace('G 2–M','G2–M').replace('ECOG 0','ECOG 0')
  return x
 (H/name).write_text(json.dumps(clean(v),ensure_ascii=False,indent=2)+'\n')
