evidence={
 '00232':{'name':'GEICAM 2000-04','citation':'Martín M et al. Lancet Oncology. 2007;8:219–225. DOI 10.1016/S1470-2045(07)70041-4','primary_url':'https://www.sciencedirect.com/science/article/pii/S1470204507700414','pubmed_url':'https://pubmed.ncbi.nlm.nih.gov/17329192/','registry_url':'https://clinicaltrials.gov/study/NCT00128310','design':'Randomised phaseIII;252women with locally recurrent/metastatic breast cancer previously treated with anthracyclines and taxanes.','comparison':'Vinorelbine alone versus gemcitabine plus vinorelbine.','schedule_applicability':'Monotherapy arm used IVvinorelbine30mg/m² Days1and8 every21days: exact NCCP00232 reference schedule.','monotherapy_results':{'median_pfs_months':4.0,'pfs_95ci_months':[2.9,5.1],'median_os_months':16.4,'os_95ci_months':[11.6,21.0],'response_percent':26,'grade3_4_neutropenia_percent':44,'febrile_neutropenia_percent':6},'comparative_results':'Adding gemcitabine improved PFS (6.0versus4.0months;HR0.66,95%CI0.50–0.88,p=.0028), without an OS difference (15.9versus16.4months;HR1.04,95%CI0.78–1.39,p=.8046).','limitations':'The comparison evaluates gemcitabine addition; it does not establish an absolute survival benefit from vinorelbine itself. Historical selected breast population; no application to ovarian/lung indications or individual prognosis. Do not compare these medians directly with oral single-arm results.','patient_summary':'Vinorelbine has shown activity in advanced breast cancer. Expected benefit depends on cancer biology, earlier treatment and health; historical trial averages do not predict an individual result.'},
 '00259':{'name':'Freyer2003 oral vinorelbine phaseII','citation':'Freyer G et al. Journal of Clinical Oncology. 2003;21:35–40. DOI 10.1200/JCO.2003.09.057','primary_url':'https://pubmed.ncbi.nlm.nih.gov/12506167/','design':'Single-arm phaseII;64patients enrolled for first-line chemotherapy of locally advanced/metastatic breast cancer;58response-evaluable.','comparison':'No randomised comparator.','schedule_applicability':'Oral60mg/m² weekly first3administrations, then conditional80mg/m²: matches NCCP00259 escalation structure. Trial initially assessed8weeks; responding/stable patients continued12weeks or longer. Do not make8or12weeks the NCCP course length.','results':{'objective_response_percent':31,'response_95ci_percent':[19,43],'response_denominator':58,'median_pfs_weeks':17.4,'median_os':'Not reached at publication','grade4_neutropenia_percent':17.2,'associated_serious_clinical_events':'4patients (6.2%)','treatment_related_deaths':0},'limitations':'Small historical first-line study with response-evaluable analysis; no causal comparative survival claim and no fixed survival estimate. Do not substitute NORBREAST228 bone-predominant outcomes or its cycle2 escalation for this schedule. Breast outcomes do not generalise to lung cancer.','patient_summary':'The oral weekly schedule has shown activity in advanced breast cancer. It needs blood tests and toxicity review even though capsules are taken at home; oral and IV doses cannot be swapped.'}}
